#if UNITY_WEBGL && DEVELOPMENT_BUILD
using System;
using System.Linq;
using System.Runtime.InteropServices;
using UnityEngine;
using UnityEngine.UIElements;
namespace BaraKitchen.Gameplay {
    // Read-only development telemetry for browser playtests. It cannot mutate gameplay.
    public class GameReviewTelemetry : MonoBehaviour {
        [DllImport("__Internal")] static extern void BaraReviewState(string json);
        [Serializable] class ButtonState {public string label;public float x,y,w,h;}
        [Serializable] class StationState {public string id,kind,item,recipe,heat;public int portions,stack,potContents;public bool potDocked;public string[] ingredients;public float x,z,scale,progress;}
        [Serializable] class Snapshot {public string phase,held,focused,working,music,workSound;public int level,score,served,missed,guests,clean,dirty;public bool training,musicPlaying,workPlaying;public int aa,audioClips,sfxCount,guestSounds;public float heldScale,workProgress,musicGain;public float remaining,x,z,fx,fz;public float cameraTilt,cameraTargetTilt,cameraYaw,cameraTargetYaw;public Rect roomBounds;public float cameraSize,viewY,viewH,rightX,rightZ,forwardX,forwardZ;public ButtonState[] uiBoxes; public string[] visibleLabels;public ButtonState[] buttons;public StationState[] stations;}
        float next;KitchenGame game;
        void Start(){game=GetComponent<KitchenGame>();}
        void Update(){if(!game||!game.chef||Time.unscaledTime<next)return;next=Time.unscaledTime+.15f;var root=GetComponent<UIDocument>().rootVisualElement;float width=root.resolvedStyle.width,height=root.resolvedStyle.height;if(!(width>0&&height>0))return;var buttons=root.Query<Button>().ToList().Where(b=>b.enabledInHierarchy&&b.resolvedStyle.display!=DisplayStyle.None&&b.worldBound.width>0&&b.worldBound.height>0&&!float.IsNaN(b.worldBound.x)&&!float.IsNaN(b.worldBound.y)).Select(b=>new ButtonState{label=b.text,x=b.worldBound.x/width,y=b.worldBound.y/height,w=b.worldBound.width/width,h=b.worldBound.height/height}).ToArray();var p=game.chef.transform.position;var f=game.chef.transform.forward;BaraReviewState(JsonUtility.ToJson(new Snapshot{phase=game.phase.ToString(),cameraTilt=game.view.Angle,cameraTargetTilt=game.Settings.cameraTilt,cameraYaw=game.view.Yaw,cameraTargetYaw=game.Settings.cameraYaw,roomBounds=game.view.RoomViewportBounds(),cameraSize=game.cam.orthographicSize,viewY=game.cam.rect.y,viewH=game.cam.rect.height,rightX=game.cam.transform.right.x,rightZ=game.cam.transform.right.z,forwardX=Vector3.ProjectOnPlane(game.cam.transform.forward,Vector3.up).normalized.x,forwardZ=Vector3.ProjectOnPlane(game.cam.transform.forward,Vector3.up).normalized.z,uiBoxes=root.Query<VisualElement>().ToList().Where(e=>e.ClassListContains("ticket")||e.ClassListContains("pot-meter")||e.ClassListContains("service-rail")||e.ClassListContains("score-feedback")).Where(e=>e.resolvedStyle.display!=DisplayStyle.None).Select(e=>new ButtonState{label=e.name+":"+string.Join(" ",e.GetClasses()),x=e.worldBound.x/width,y=e.worldBound.y/height,w=e.worldBound.width/width,h=e.worldBound.height/height}).ToArray(),visibleLabels=root.Query<Label>().ToList().Where(e=>e.resolvedStyle.display!=DisplayStyle.None&&e.worldBound.width>0).Select(e=>e.text).ToArray(),working=game.chef.working?game.chef.workLabel:"",workProgress=game.chef.workProgress,heldScale=game.chef.held?game.chef.held.transform.lossyScale.x:0,music=game.sound.mode,musicPlaying=game.sound.MusicPlaying,workPlaying=game.sound.WorkPlaying,workSound=game.sound.workId,musicGain=game.sound.MusicGain,audioClips=game.sound.ClipCount,sfxCount=game.sound.effectsPlayed,guestSounds=game.sound.guestCalls,aa=QualitySettings.antiAliasing,level=game.level.id,score=game.book.score,served=game.book.served,missed=game.book.missed,guests=game.guests.Count,clean=game.rack.Count,dirty=game.returns.Count,training=game.training,remaining=game.remaining,held=game.chef.held?game.chef.held.Label:"",focused=game.chef.focused?game.chef.focused.id:"",x=p.x,z=p.z,fx=f.x,fz=f.z,buttons=buttons,stations=game.stations.Select(s=>new StationState{id=s.id,kind=s.kind,item=s.item?s.item.Label:"",recipe=s.item?s.item.Recipe:"",portions=s.item?s.item.portions.Count:0,ingredients=s.item?s.item.portions.Select(i=>i.Label).ToArray():Array.Empty<string>(),stack=s.items.Count,potContents=s.potContents,potDocked=s.PotDocked,heat=s.hazard?s.hazard.state.ToString():"",scale=s.item?s.item.transform.lossyScale.x:0,progress=s.item?s.item.prep:0,x=s.transform.position.x,z=s.transform.position.z}).ToArray()}));}
    }
}
#endif
